import js from "@eslint/js";
import { defineConfig, globalIgnores } from "eslint/config";
import globals from "globals";
import tseslint from "typescript-eslint";

/**
 * Flat ESLint config (eslint 10 + typescript-eslint 8, plan 7.1).
 *
 * `src/contracts/` is generated by `uv run tools/gen_contracts.py`; it is
 * typechecked (tests/contracts.test.ts imports it) but never linted, so a
 * generator change can never fail `npm run lint`.
 */
export default defineConfig(
  globalIgnores([
    "dist/**",
    "node_modules/**",
    "src/contracts/**",
    "playwright-report/**",
    "test-results/**",
  ]),
  js.configs.recommended,
  tseslint.configs.recommended,
  {
    files: ["src/**/*.{ts,tsx}"],
    languageOptions: { globals: globals.browser },
  },
  {
    files: ["tests/**/*.{ts,tsx}"],
    languageOptions: { globals: { ...globals.browser, ...globals.node } },
  },
  {
    files: ["scripts/**/*.mjs"],
    languageOptions: { globals: { ...globals.browser, ...globals.node } },
  },
  {
    files: ["*.config.{js,ts}", "eslint.config.js"],
    languageOptions: { globals: globals.node },
  },
  {
    rules: {
      // The app is strict TypeScript; unused values are errors in tsc too.
      "@typescript-eslint/no-unused-vars": [
        "error",
        { argsIgnorePattern: "^_", varsIgnorePattern: "^_" },
      ],
      "@typescript-eslint/consistent-type-imports": [
        "error",
        { prefer: "type-imports", fixStyle: "separate-type-imports" },
      ],
      "no-console": ["error", { allow: ["warn", "error"] }],
    },
  },
);
